#!/usr/bin/env node
// Phase 2 step 19: rollup of every domains/<d>/backend-mapping.md into reference/backend-mapping.md.

import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { DOCS_ROOT, APP_ROOT } from '../_lib/paths.mjs';

const ROOT = DOCS_ROOT;
const DOMAINS = resolve(ROOT, 'usecases/domains');
const OUT = resolve(ROOT, 'usecases/reference/backend-mapping.md');

const parts = [
  '# Backend Mapping — All Domains (Rollup)',
  '',
  '> Auto-generated by `scripts/usecases/_build-backend-rollup.mjs` (Phase 2 step 19). Concatenates every `domains/*/backend-mapping.md`. Source of truth remains the per-domain files.',
  '>',
  '> Sentinel rule per ADR-0005 D3: every cell is either a real `*.api.js` export, a real store action, an entity from `docs/erd/README.md`, or the literal `BACKEND_NOT_DESIGNED`. State-based check enforced by `scripts/usecases/check-backend-sentinel.mjs`.',
  '',
  '---',
  '',
];

const dirs = readdirSync(DOMAINS).sort();
for (const d of dirs) {
  const path = resolve(DOMAINS, d, 'backend-mapping.md');
  if (!existsSync(path)) {
    parts.push(`## ${d}`, '', '_(no backend-mapping.md present — domain skipped)_', '');
    continue;
  }
  const txt = readFileSync(path, 'utf8');
  parts.push(`## Domain — \`${d}\``, '', `_Source: \`docs/usecases/domains/${d}/backend-mapping.md\`_`, '');
  // Strip leading H1 from the per-domain file to avoid duplicating it
  const noH1 = txt.replace(/^# .+\n+/, '');
  parts.push(noH1.trimEnd(), '', '---', '');
}

writeFileSync(OUT, parts.join('\n') + '\n');
console.log(`Wrote ${OUT} from ${dirs.length} domain files`);
